function sourced(
  id: string,
  sectionId: string,
  stem: string,
  options: [
    { text: string; why: string; correct?: boolean },
    { text: string; why: string; correct?: boolean },
    { text: string; why: string; correct?: boolean },
    { text: string; why: string; correct?: boolean },
  ],
): Question {
  return { ...question(id, stem, options), sectionId } as Question
}

